ALTER POLICY "products public read" ON public.products USING ((active AND NOT archived) OR public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.normalize_order_items(_items jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE it jsonb; q numeric; result jsonb; BEGIN IF _items IS NULL OR jsonb_typeof(_items)<>'array' OR jsonb_array_length(_items)<1 OR jsonb_array_length(_items)>30 THEN RAISE EXCEPTION 'EMPTY_CART'; END IF; FOR it IN SELECT * FROM jsonb_array_elements(_items) LOOP q:=(it->>'quantity')::numeric; IF q IS NULL OR q<>trunc(q) OR q<1 OR q>100 OR it->>'variant_id' IS NULL THEN RAISE EXCEPTION 'INVALID_QTY'; END IF; END LOOP; SELECT jsonb_agg(jsonb_build_object('variant_id',id,'quantity',qty) ORDER BY id) INTO result FROM (SELECT (value->>'variant_id')::uuid id,sum((value->>'quantity')::integer) qty FROM jsonb_array_elements(_items) GROUP BY 1) s; IF EXISTS(SELECT 1 FROM jsonb_array_elements(result) WHERE (value->>'quantity')::integer>100) THEN RAISE EXCEPTION 'INVALID_QTY'; END IF; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.place_order(_name text,_phone text,_city text,_address text,_notes text,_items jsonb,_coupon text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.store_settings; it jsonb; v record; oid uuid; num text; q integer; result jsonb; dis numeric; eligible_total numeric:=0; line_dis numeric; remaining numeric; eligible_count integer:=0; idx integer:=0; c public.coupons; items jsonb; is_eligible boolean; BEGIN SELECT * INTO s FROM public.store_settings WHERE id=1; IF NOT coalesce(s.cod_enabled,false) THEN RAISE EXCEPTION 'COD_DISABLED'; END IF; IF _name IS NULL OR length(trim(_name))<2 OR length(_name)>100 THEN RAISE EXCEPTION 'INVALID_NAME'; END IF; IF _phone IS NULL OR _phone !~ '^01[0125][0-9]{8}$' THEN RAISE EXCEPTION 'INVALID_PHONE'; END IF; IF _address IS NULL OR length(trim(_address))<10 OR length(_address)>500 THEN RAISE EXCEPTION 'INVALID_ADDRESS'; END IF; IF length(_notes)>500 THEN RAISE EXCEPTION 'INVALID_NOTES'; END IF; items:=public.normalize_order_items(_items);
PERFORM 1 FROM public.product_variants WHERE id IN (SELECT (value->>'variant_id')::uuid FROM jsonb_array_elements(items)) ORDER BY id FOR UPDATE;
IF length(trim(coalesce(_coupon,'')))>0 THEN SELECT * INTO c FROM public.coupons WHERE code=upper(trim(_coupon)) FOR UPDATE; END IF;
result:=public.quote_order(items,_city,_coupon); dis:=(result->>'discount')::numeric; remaining:=dis;
IF dis>0 THEN FOR it IN SELECT * FROM jsonb_array_elements(items) LOOP SELECT pv.*,p.category_id INTO v FROM public.product_variants pv JOIN public.products p ON p.id=pv.product_id WHERE pv.id=(it->>'variant_id')::uuid; IF (cardinality(c.product_ids)=0 AND cardinality(c.category_ids)=0) OR v.product_id=ANY(c.product_ids) OR v.category_id=ANY(c.category_ids) THEN eligible_total:=eligible_total+coalesce(v.sale_price,v.price)*(it->>'quantity')::integer; eligible_count:=eligible_count+1; END IF; END LOOP; END IF;
num:='KT-'||to_char(now(),'YYMMDD')||'-'||upper(substr(md5(gen_random_uuid()::text),1,6)); INSERT INTO public.orders(order_number,customer_name,phone,city,address,notes,subtotal,shipping_fee,discount,total,coupon_code) VALUES(num,trim(_name),_phone,_city,trim(_address),nullif(trim(_notes),''),(result->>'subtotal')::numeric,(result->>'shipping_fee')::numeric,dis,(result->>'total')::numeric,nullif(upper(trim(_coupon)),'')) RETURNING id INTO oid;
PERFORM set_config('app.stock_reason','طلب '||num,true);
FOR it IN SELECT * FROM jsonb_array_elements(items) LOOP q:=(it->>'quantity')::integer; SELECT pv.*,p.name_ar,p.category_id INTO v FROM public.product_variants pv JOIN public.products p ON p.id=pv.product_id WHERE pv.id=(it->>'variant_id')::uuid; IF v.stock<q THEN RAISE EXCEPTION 'OUT_OF_STOCK'; END IF; UPDATE public.product_variants SET stock=stock-q WHERE id=v.id; line_dis:=0; is_eligible:=dis>0 AND ((cardinality(c.product_ids)=0 AND cardinality(c.category_ids)=0) OR v.product_id=ANY(c.product_ids) OR v.category_id=ANY(c.category_ids)); IF is_eligible THEN idx:=idx+1; line_dis:=CASE WHEN idx=eligible_count THEN remaining ELSE least(remaining,round(dis*(coalesce(v.sale_price,v.price)*q)/eligible_total,2)) END; remaining:=remaining-line_dis; END IF; INSERT INTO public.order_items(order_id,variant_id,product_name,size_label,unit_price,regular_price,discount_amount,quantity) VALUES(oid,v.id,v.name_ar,v.size_label,coalesce(v.sale_price,v.price),v.price,line_dis,q); END LOOP;
IF dis>0 THEN PERFORM set_config('app.redeeming_coupon','true',true); UPDATE public.coupons SET used_count=used_count+1 WHERE id=c.id; END IF; RETURN result||jsonb_build_object('order_number',num); END $$;
CREATE TRIGGER coupon_usage_counter BEFORE UPDATE OF used_count ON public.coupons FOR EACH ROW EXECUTE FUNCTION public.valid_coupon_usage();
CREATE OR REPLACE FUNCTION public.order_snapshot_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF ROW(NEW.subtotal,NEW.total,NEW.shipping_fee,NEW.discount,NEW.coupon_code,NEW.order_number) IS DISTINCT FROM ROW(OLD.subtotal,OLD.total,OLD.shipping_fee,OLD.discount,OLD.coupon_code,OLD.order_number) THEN RAISE EXCEPTION 'ORDER_SNAPSHOT_IMMUTABLE'; END IF; RETURN NEW; END $$;
CREATE TRIGGER order_snapshot_guard BEFORE UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.order_snapshot_guard();